// Fetch the next 5 upcoming events
const res = await fetch(
  "https://dashboard.all-ai-network.org/api/v1/events?upcoming=true&limit=5",
  {
    headers: { Authorization: `Bearer ${process.env.AAIN_API_KEY}` },
  }
);
const { events } = await res.json();

// Render however you like
events.forEach((e) => {
  console.log(e.title, new Date(e.date).toLocaleString());
});

